<?php
declare(strict_types=1);require __DIR__.'/../config/config.php';
function h($v){return htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');}
$u=current_user();
$action=$_GET['action']??'dashboard';
if($_SERVER['REQUEST_METHOD']==='POST'&&$action==='add_medicine'){$s=db()->prepare('INSERT INTO medicines (name,generic_name,strength,manufacturer,barcode,unit_name,units_per_strip,strips_per_box,purchase_price,retail_unit_price,reorder_level,min_profit_margin_pct) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)');$s->execute([trim($_POST['name']),trim($_POST['generic_name']??''),trim($_POST['strength']??''),trim($_POST['manufacturer']??''),trim($_POST['barcode']??'')?:null,trim($_POST['unit_name']??'tablet')?:'tablet',max(1,(int)($_POST['units_per_strip']??1)),max(1,(int)($_POST['strips_per_box']??1)),max(0,(float)($_POST['purchase_price']??0)),max(0,(float)($_POST['retail_unit_price']??0)),max(0,(int)($_POST['reorder_level']??0)),min(100,max(0,(float)($_POST['min_profit_margin_pct']??10)))]);audit_log('medicine_created','Medicine: '.trim($_POST['name']));header('Location: index.php?action=medicines&saved=1');exit;}
if($_SERVER['REQUEST_METHOD']==='POST'&&$action==='sale'){$items=json_decode($_POST['items']??'[]',true)?:[];if(!$items)exit('Cart is empty.');$method=$_POST['payment_method']??'cash';$customerId=(int)($_POST['customer_id']??0);if($method==='credit'&&!$customerId)exit('Customer is required for a credit sale.');if($method!=='credit')$customerId=0;$pdo=db();$pdo->beginTransaction();try{$sub=0;$maxDiscount=0;foreach($items as $x){$sub+=(float)$x['price']*(int)$x['qty'];$qty=max(1,(int)$x['qty']);$mid=(int)$x['id'];$b=$pdo->prepare('SELECT b.*,m.min_profit_margin_pct FROM batches b JOIN medicines m ON m.id=b.medicine_id WHERE b.medicine_id=? AND b.units_remaining>=? AND (b.expiry_date IS NULL OR b.expiry_date>=CURDATE()) ORDER BY b.expiry_date IS NULL,b.expiry_date,b.id LIMIT 1 FOR UPDATE');$b->execute([$mid,$qty]);$batch=$b->fetch();if(!$batch)throw new RuntimeException('No valid stock available for '.($x['name']??'medicine').'.');$unitPrice=(float)$x['price']/$qty;$minimum=(float)$batch['purchase_unit_cost']*(1+(float)$batch['min_profit_margin_pct']/100);$maxDiscountPerUnit=max(0,$unitPrice-$minimum);$maxDiscount+=(float)$maxDiscountPerUnit*$qty;}$disc=max(0,(float)($_POST['discount']??0));if($disc>$maxDiscount+0.01)throw new RuntimeException('Discount exceeds the allowed minimum-profit limit. Maximum discount for this sale is Rs. '.number_format($maxDiscount,2));$total=max(0,$sub-$disc);$paid=max(0,(float)($_POST['paid']??$total));if($paid>$total)throw new RuntimeException('Amount received cannot exceed sale total.');if($method!=='credit'&&$paid<$total)throw new RuntimeException('Amount received must cover the sale total.');$inv='INV-'.date('YmdHis').'-'.random_int(100,999);$pdo->prepare('INSERT INTO sales(invoice_no,customer_id,subtotal,discount,total,payment_method,paid) VALUES(?,?,?,?,?,?,?)')->execute([$inv,$customerId?:null,$sub,$disc,$total,$method,$paid]);$sid=(int)$pdo->lastInsertId();foreach($items as $x){$qty=max(1,(int)$x['qty']);$mid=(int)$x['id'];$b=$pdo->prepare('SELECT b.* FROM batches b WHERE b.medicine_id=? AND b.units_remaining>=? AND (b.expiry_date IS NULL OR b.expiry_date>=CURDATE()) ORDER BY b.expiry_date IS NULL,b.expiry_date,b.id FOR UPDATE');$b->execute([$mid,$qty]);$batch=$b->fetch();if(!$batch)throw new RuntimeException('Insufficient valid stock for '.($x['name']??'medicine'));$price=(float)$x['price']/$qty;$pdo->prepare('INSERT INTO sale_items(sale_id,medicine_id,batch_id,quantity_units,unit_price,line_total) VALUES(?,?,?,?,?,?)')->execute([$sid,$mid,$batch['id'],$qty,$price,$price*$qty]);$pdo->prepare('UPDATE batches SET units_remaining=units_remaining-? WHERE id=?')->execute([$qty,$batch['id']]);$pdo->prepare('INSERT INTO stock_movements(medicine_id,batch_id,movement_type,quantity_units,reference_id,note) VALUES(?,?,"sale",?,?,?)')->execute([$mid,$batch['id'],-$qty,$sid,'POS sale']);}$pdo->commit();audit_log('sale_completed','Invoice '.$inv.' · Rs. '.number_format($total,2).' · Payment: '.$method.' · Discount: Rs. '.number_format($disc,2));header('Location: index.php?action=receipt&id='.$sid);exit;}catch(Throwable $e){$pdo->rollBack();http_response_code(400);exit('Sale failed: '.h($e->getMessage()));}}
if($action==='pos'){header('Location: pos.php');exit;}if($action==='inventory'){header('Location: inventory.php');exit;}
echo '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.h(APP_NAME).'</title><link rel="stylesheet" href="style.css"></head><body><header><div class="brand">💊 '.h(APP_NAME).'</div><nav><a href="index.php">Dashboard</a><a href="pos.php">POS</a><a href="index.php?action=medicines">Medicines</a><a href="inventory.php">Inventory</a><a href="manage.php">Management</a><a href="index.php?action=reports">Reports</a><span style="margin-left:12px">👤 '.h($u['username']).' · '.h(ucfirst($u['role'])).'</span><a href="logout.php">Logout</a></nav></header><main>';
if($action==='dashboard'){$sales=(float)db()->query('SELECT COALESCE(SUM(total),0)n FROM sales WHERE DATE(created_at)=CURDATE()')->fetch()['n'];$meds=(int)db()->query('SELECT COUNT(*)n FROM medicines WHERE active=1')->fetch()['n'];$stock=(int)db()->query('SELECT COALESCE(SUM(units_remaining),0)n FROM batches')->fetch()['n'];?><div class="page-title"><div><div class="eyebrow">PHARMACY MANAGEMENT</div><h1>Dashboard</h1><p>Sales, stock and loose-tablet management.</p></div><a class="btn" href="pos.php">Open POS →</a></div><div class="cards"><div><span>Today's sales</span><b>Rs. <?=number_format($sales,2)?></b></div><div><span>Medicines</span><b><?=$meds?></b></div><div><span>Units in stock</span><b><?=number_format($stock)?></b></div></div><div class="quick-grid"><a href="pos.php"><strong>⚡ Fast Sale</strong><small>Box · Strip · Tablet</small></a><a href="inventory.php"><strong>📦 Receive Stock</strong><small>Batch and expiry optional</small></a><a href="manage.php"><strong>⚙ Management</strong><small>Suppliers · Customers · Expenses · Reports</small></a></div><?php }
elseif($action==='medicines'){$rows=db()->query('SELECT * FROM medicines WHERE active=1 ORDER BY name')->fetchAll();?><div class="page-title"><div><div class="eyebrow">CATALOGUE</div><h1>Medicines</h1><p>Set tablet, strip and box conversion.</p></div></div><?php if(isset($_GET['saved'])):?><div class="success">✓ Medicine saved.</div><?php endif;?><section class="panel"><h2>Add Medicine</h2><form method="post" action="?action=add_medicine" class="grid"><input name="name" placeholder="Brand name *" required><input name="generic_name" placeholder="Generic name"><input name="strength" placeholder="Strength"><input name="manufacturer" placeholder="Manufacturer"><input name="barcode" placeholder="Barcode"><input name="unit_name" value="tablet" placeholder="Smallest unit"><input type="number" name="units_per_strip" value="10" min="1" placeholder="Tablets/strip"><input type="number" name="strips_per_box" value="10" min="1" placeholder="Strips/box"><input type="number" step="0.01" name="purchase_price" value="0" min="0" placeholder="Purchase price/tablet"><input type="number" step="0.01" name="retail_unit_price" value="0" min="0" placeholder="Retail price/tablet *" required><input type="number" name="reorder_level" value="20" min="0" placeholder="Reorder level"><input type="number" step="0.01" name="min_profit_margin_pct" value="10" min="0" max="100" placeholder="Minimum profit margin %"><button class="btn">Save Medicine</button></form></section><section class="panel"><table><tr><th>Medicine</th><th>Conversion</th><th>Retail/tablet</th><th>Min margin</th><th>Stock</th></tr><?php foreach($rows as $r):$q=db()->prepare('SELECT COALESCE(SUM(units_remaining),0)n FROM batches WHERE medicine_id=?');$q->execute([$r['id']]);$st=(int)$q->fetch()['n'];?><tr><td><b><?=h($r['name'])?></b><small><?=h($r['generic_name'])?> <?=h($r['strength'])?></small></td><td><?=$r['units_per_strip']?>/strip × <?=$r['strips_per_box']?> strips/box</td><td>Rs. <?=number_format((float)$r['retail_unit_price'],2)?></td><td><?=number_format((float)$r['min_profit_margin_pct'],2)?>%</td><td><?=number_format($st)?></td></tr><?php endforeach;?></table></section><?php }
elseif($action==='reports'){header('Location: manage.php?tab=reports');exit;}
elseif($action==='receipt'){$q=db()->prepare('SELECT s.*,c.name customer_name FROM sales s LEFT JOIN customers c ON c.id=s.customer_id WHERE s.id=?');$q->execute([(int)($_GET['id']??0)]);$sale=$q->fetch();if(!$sale)exit('Sale not found.');$q=db()->prepare('SELECT si.*,m.name FROM sale_items si JOIN medicines m ON m.id=si.medicine_id WHERE si.sale_id=?');$q->execute([$sale['id']]);$items=$q->fetchAll();?><section class="panel receipt"><div class="eyebrow">SALE COMPLETE</div><h1><?=h(APP_NAME)?></h1><p>Invoice: <b><?=h($sale['invoice_no'])?></b><?php if($sale['customer_name']):?> · Customer: <b><?=h($sale['customer_name'])?></b><?php endif;?></p><?php foreach($items as $x):?><div class="cartrow"><span><?=h($x['name'])?> × <?=number_format($x['quantity_units'])?></span><b>Rs. <?=number_format((float)$x['line_total'],2)?></b></div><?php endforeach;?><div class="grand">Total <strong>Rs. <?=number_format((float)$sale['total'],2)?></strong></div><div>Paid: Rs. <?=number_format((float)$sale['paid'],2)?> · Due: Rs. <?=number_format(max(0,(float)$sale['total']-(float)$sale['paid']),2)?></div><button class="btn" onclick="window.print()">Print Receipt</button> <a class="btn" href="pos.php">New Sale</a></section><?php }
else{header('Location: index.php');exit;}echo '</main></body></html>';